function report(){const d=day(),tot=d.c+d.w,acc=tot?Math.round(d.c/tot*100):0;
 const m=Object.entries(d.miss).sort((a,b)=>b[1]-a[1]).slice(0,4);
 const cf=Object.entries(d.conf||{}).sort((a,b)=>b[1]-a[1]).slice(0,3);
 let t="LAPORAN HARI "+dayNo()+" ("+today()+")\nTahap sekarang: "+ST[S.stage].l+"\nSoal dijawab: "+tot+" | Benar: "+d.c+" | Salah: "+d.w+" | Akurasi: "+acc+"%\n";
 t+="Huruf yang sudah lancar: "+(Object.keys(S.mastered||{}).join(" ")||"belum ada")+"\n";
 t+="Huruf paling sering salah: "+(m.length?m.map(x=>x[0]+" ("+x[1]+"×)").join(", "):"tidak ada")+"\n";
 if(cf.length)t+="Sering tertukar: "+cf.map(x=>x[0]+" ("+x[1]+"×)").join(", ")+"\n";
 t+="\nFeedback: ";
 t+=!tot?"Belum ada soal hari ini. Mulai dengan 10 soal dulu.":acc>=90?"Sangat bagus. Pertahankan, besok lanjut ke tahap berikutnya.":acc>=75?"Cukup baik. Fokus ulangi huruf yang sering salah sebelum lanjut.":"Masih banyak yang tertukar. Ulangi tahap ini besok dan perhatikan tips tiap huruf.";
 const ks=Object.keys(S.days).sort();
 if(ks.length>1)t+="\n\nRiwayat akurasi: "+ks.map((k,i)=>{const x=S.days[k],n=x.c+x.w;return"H"+(i+1)+" "+(n?Math.round(x.c/n*100):0)+"%"}).join(", ");
 t+="\n\nTempel laporan ini ke chat Claude supaya kita bahas dan susun materi besok.\nAplikasi Latihan Bahasa Jepang oleh TriNaldi.";return t}
$("rep").onclick=()=>{const c=$("rc");c.style.display="block";c.innerHTML="<pre></pre>";c.firstChild.textContent=report();
 const b=document.createElement("button");b.className="ghost";b.textContent="Salin laporan";b.style.marginTop="12px";
 b.onclick=()=>{try{navigator.clipboard.writeText(report()).then(()=>b.textContent="Tersalin")}catch(e){b.textContent="Pilih teks lalu salin manual"}};c.appendChild(b);c.scrollIntoView({behavior:"smooth"})};
