const ymd=d=>d.getFullYear()+'-'+String(d.getMonth()+1).padStart(2,'0')+'-'+String(d.getDate()).padStart(2,'0');
const nz=s=>(s||'').toLowerCase().replace(/[^a-z0-9]/g,'');
const nrm=s=>(s||'').replace(/[\s、。！？!?,.\-～ー「」]/g,'');
const TIPS2=[[/[らりるれろ]/,'Baris ら: ujung lidah menyentuh langit-langit sekali, antara r dan l.'],[/っ/,'っ kecil: tahan sebentar sebelum konsonan berikutnya.'],[/ん/,'ん: nasal, tahan satu ketukan penuh.'],[/ふ/,'ふ: antara h dan f, bibir tidak mengatup rapat.'],[/つ/,'つ: ts + u.'],[/[ゃゅょ]/,'ゃ ゅ ょ kecil menyatu dengan huruf sebelumnya.']];
function align(a,b){a=[...nrm(a)];b=[...nrm(b)];const n=a.length,m=b.length,d=Array.from({length:n+1},()=>Array(m+1).fill(0));for(let i=n-1;i>=0;i--)for(let j=m-1;j>=0;j--)d[i][j]=a[i]===b[j]?d[i+1][j+1]+1:Math.max(d[i+1][j],d[i][j+1]);const ok=Array(n).fill(false);let i=0,j=0;while(i<n&&j<m){if(a[i]===b[j]){ok[i]=true;i++;j++}else if(d[i+1][j]>=d[i][j+1])i++;else j++}return{a,ok,sc:n?d[0][0]/Math.max(n,m):0}}
function pr(t,h){let best=null;for(const x of [t.j||t.k,t.v]){if(!x)continue;const r=align(x,h);if(!best||r.sc>best.sc)best=r}if(!best)best=align('',h);const txt=best.a.join(''),tp=TIPS2.filter(([r])=>r.test(txt)).slice(0,2).map(x=>x[1]).join(' ');
 return{pct:Math.round(best.sc*100),html:'<div style="margin-top:8px;font-size:22px;letter-spacing:2px">'+best.a.map((c,i)=>'<span style="color:var('+(best.ok[i]?'--ok':'--no')+')">'+c+'</span>').join('')+'</div><div class="mu">Hijau = terdengar benar, merah = belum terdengar.'+(tp?' Tips: '+tp:'')+'</div>'}}
const SRC=()=>window.SpeechRecognition||window.webkitSpeechRecognition;
function micPractice(){const SR=SRC(),box=$('pf');if(!SR){box.innerHTML='<div class="fb no">Browser belum mendukung pengenalan suara. Coba Chrome atau Edge.</div>';return}
 const r=new SR();r.lang='ja-JP';r.maxAlternatives=3;box.innerHTML='<div class="mu">Mendengarkan…</div>';
 r.onresult=e=>{const L=e.results[0];let b=null;for(let i=0;i<L.length;i++){const p=pr(q.t,L[i].transcript);if(!b||p.pct>b.pct){b=p;b.h=L[i].transcript}}box.innerHTML='<div class="fb '+(b.pct>=60?'ok':'no')+'"><b>'+(b.pct>=85?'Pengucapan sangat jelas!':b.pct>=60?'Cukup jelas.':'Belum jelas, coba lagi pelan-pelan.')+'</b> Terdengar: '+b.h+' ('+b.pct+'%)'+b.html+'</div>'};
 r.onerror=e=>{box.innerHTML='<div class="fb no">Mikrofon tidak bisa dipakai ('+e.error+'). Izinkan mikrofon lalu coba lagi.</div>'};
 try{r.start()}catch(e){}}
function micAnswer(){const SR=SRC(),box=$('pf');if(!SR){box.innerHTML='<div class="fb no">Browser belum mendukung pengenalan suara. Coba Chrome atau Edge, atau pilih dengan klik.</div>';return}
 const r=new SR();r.lang='ja-JP';r.maxAlternatives=3;box.innerHTML='<div class="mu">Ucapkan balasanmu…</div>';
 r.onresult=e=>{const L=e.results[0];let best={p:0};for(let i=0;i<L.length;i++)for(const o of q.o){const p=align(o.j||'',L[i].transcript).sc;if(p>best.p)best={p,o,h:L[i].transcript}}
  if(best.p<.4){box.innerHTML='<div class="fb no">Suaramu belum terbaca jelas. Coba lagi lebih pelan, atau pilih dengan klik.</div>';return}
  q.heard=best.h+' ('+Math.round(best.p*100)+'%)';sel=best.o.r;check()};
 r.onerror=e=>{box.innerHTML='<div class="fb no">Mikrofon tidak bisa dipakai ('+e.error+'). Izinkan mikrofon lalu coba lagi.</div>'};
 try{r.start()}catch(e){}}
function pad(ch){const h=$('pad');h.innerHTML='<canvas id="cv" width="300" height="300" style="touch-action:none;border:1px solid var(--bd);border-radius:12px;background:var(--sf);display:block;margin:10px auto;max-width:100%"></canvas><div class="row" style="justify-content:center"><button class="ghost" id="cl">Hapus</button></div><div class="mu">Tulis mengikuti bayangan huruf, goresan dari atas ke bawah dan kiri ke kanan.</div>';
 const c=$('cv'),x=c.getContext('2d');const guide=()=>{x.clearRect(0,0,300,300);x.fillStyle='rgba(128,128,128,.28)';x.font=Math.min(220,Math.floor(270/Math.max(1,[...ch].length)))+'px sans-serif';x.textAlign='center';x.textBaseline='middle';x.fillText(ch,150,160)};guide();
 x.lineWidth=10;x.lineCap='round';x.strokeStyle=getComputedStyle(document.body).color;let dr=false;
 const pt=e=>{const r=c.getBoundingClientRect();return[(e.clientX-r.left)*300/r.width,(e.clientY-r.top)*300/r.height]};
 c.onpointerdown=e=>{dr=true;const p=pt(e);x.beginPath();x.moveTo(p[0],p[1]);try{c.setPointerCapture(e.pointerId)}catch(_){}};
 c.onpointermove=e=>{if(!dr)return;const p=pt(e);x.lineTo(p[0],p[1]);x.stroke()};c.onpointerup=()=>{dr=false};$('cl').onclick=guide}
function toast(m){const t=document.createElement('div');t.className='toast';t.textContent=m;document.body.appendChild(t);setTimeout(()=>t.remove(),2200)}
function confetti(){const c=document.createElement('canvas');c.style.cssText='position:fixed;inset:0;pointer-events:none;z-index:50;width:100%;height:100%';c.width=innerWidth;c.height=innerHeight;document.body.appendChild(c);const x=c.getContext('2d'),P=Array.from({length:90},()=>({x:Math.random()*c.width,y:-20-Math.random()*c.height*.5,v:2+Math.random()*4,r:3+Math.random()*4,h:Math.random()*360,s:Math.random()*2-1}));let f=0;(function a(){x.clearRect(0,0,c.width,c.height);P.forEach(p=>{p.y+=p.v;p.x+=p.s;x.fillStyle='hsl('+p.h+',80%,60%)';x.fillRect(p.x,p.y,p.r,p.r*1.6)});if(++f<150)requestAnimationFrame(a);else c.remove()})()}
