function review(){const wk=Object.entries(S.h).filter(e=>e[1].w>0).sort((a,b)=>b[1].w-a[1].w).map(e=>e[0]);const kana=R.flatMap(r=>r.c),words=ALLW;
 let it=wk.map(k=>words.find(c=>c.k===k)).filter(Boolean).slice(0,12),isw=true;if(it.length<4){it=wk.map(k=>kana.find(c=>c.k===k)).filter(Boolean).slice(0,12);isw=false}
 if(it.length<4){toast('Butuh minimal 4 item yang pernah salah');return}
 if(!RVB)RVB={i:S.stage,s:ST[S.stage],cur:S.cur};window._rvb=RVB;ST[S.stage]={l:'Perbaikan: item lemah',rv:1,ch:it,t:2,w:isw?1:0};S.cur={};stageDone=false;show('latih');next()}
