 if(!done&&s.dlg&&q.t.j){const o=qc.querySelector('.opts');if(o){o.insertAdjacentHTML('afterend','<div class="row" style="justify-content:center"><button class="ghost" id="ma">Jawab dengan suara</button></div><div id="pf"></div>');$('ma').onclick=micAnswer}}
