 const due=P.filter(c=>F[c.k]&&F[c.k].d<=now).sort((a,b)=>F[a.k].d-F[b.k].d),nw=P.filter(c=>!F[c.k]),mast=P.filter(c=>F[c.k]&&F[c.k].b>=3).length;
