const RK={};'a あ i い u う e え o お ka か ki き ku く ke け ko こ sa さ shi し si し su す se せ so そ ta た chi ち ti ち tsu つ tu つ te て to と na な ni に nu ぬ ne ね no の ha は hi ひ fu ふ hu ふ he へ ho ほ ma ま mi み mu む me め mo も ya や yu ゆ yo よ ra ら ri り ru る re れ ro ろ wa わ wo を ga が gi ぎ gu ぐ ge げ go ご za ざ ji じ zi じ zu ず ze ぜ zo ぞ da だ di ぢ du づ de で do ど ba ば bi び bu ぶ be べ bo ぼ pa ぱ pi ぴ pu ぷ pe ぺ po ぽ kya きゃ kyu きゅ kyo きょ sha しゃ shu しゅ sho しょ sya しゃ syu しゅ syo しょ cha ちゃ chu ちゅ cho ちょ tya ちゃ tyu ちゅ tyo ちょ nya にゃ nyu にゅ nyo にょ hya ひゃ hyu ひゅ hyo ひょ mya みゃ myu みゅ myo みょ rya りゃ ryu りゅ ryo りょ gya ぎゃ gyu ぎゅ gyo ぎょ ja じゃ ju じゅ jo じょ bya びゃ byu びゅ byo びょ pya ぴゃ pyu ぴゅ pyo ぴょ fa ふぁ fi ふぃ fe ふぇ fo ふぉ'.split(' ').forEach((x,i,a)=>{if(i%2===0)RK[x]=a[i+1]});
function r2k(s,kata){s=s.toLowerCase();let o='',i=0;
 while(i<s.length){const c=s[i],c2=s[i+1];
  if(!/[a-z\-]/.test(c)){o+=c;i++;continue}
  if(c==='-'){o+='ー';i++;continue}
  if(c2&&((c===c2&&/[kstpcgbdzfjhmrwyv]/.test(c))||(c==='t'&&c2==='c'))){o+='っ';i++;continue}
  let m=null;for(let n=3;n>=1;n--){const k=s.substr(i,n);if(RK[k]){m=[k,RK[k]];break}}
  if(m){o+=m[1];i+=m[0].length;continue}
  if(c==='n'&&c2){if(c2==='n'){o+='ん';i+=/[aiueoy]/.test(s[i+2]||'')?1:2;continue}if(/[a-z]/.test(c2)&&!/[aiueoy]/.test(c2)){o+='ん';i++;continue}}
  o+=s.slice(i);break}
 return kata?[...o].map(ch=>ch>='\u3041'&&ch<='\u3096'?String.fromCharCode(ch.charCodeAt(0)+96):ch).join(''):o}
const nrt=s=>(s||'').replace(/[\s、。！？!?,.　]/g,'');
function recd(ok,k){const d=day();S.h[k]=S.h[k]||{c:0,w:0};S.mastered=S.mastered||{};if(ok){d.c++;S.h[k].c++;S.cur[k]=(S.cur[k]||0)+1;if(S.cur[k]>=ST[S.stage].t)S.mastered[k]=true}else{d.w++;S.h[k].w++;S.cur[k]=0;delete S.mastered[k];d.miss[k]=(d.miss[k]||0)+1}S.last=k}
function tyAcc(t){const a=[t.k,t.v];if(HAS_KANJI.test(t.k))a.push(r2k(t.r).replace(/n$/,'ん'));const b=a.filter(Boolean).map(nrt);b.slice().forEach(x=>{if(x.length>=5)b.push(x.replace(/は/g,'わ').replace(/を/g,'お').replace(/へ/g,'え'))});return b}
function tyRender(qc,s){const t=q.t,hm=s.hint==='m'&&t.m,pm=hm?t.m:(t.m?t.r+'<div class="mu" style="font-size:14px;font-weight:400">'+t.m+'</div>':t.r);
 qc.innerHTML='<div class="mu">Menulis · '+s.l+'</div><div class="kana" style="font-size:'+(String(hm?t.m:t.r).length>16?24:40)+'px">'+pm+'</div><div>'+(hm?'Tulis dalam bahasa Jepang':'Ketik dalam huruf Jepang')+'</div><input id="ty" autocomplete="off" autocapitalize="off" spellcheck="false" placeholder="Ketik di sini" style="display:block;margin:14px auto;width:min(340px,100%);padding:12px 14px;font-size:20px;text-align:center;border-radius:10px;border:1px solid var(--bd);background:var(--sf);color:var(--tx)"'+(done?' disabled':'')+'><div id="fb">'+(q.res||'')+'</div>'+(hm&&!done?'':'<div class="row" style="justify-content:center"><button class="ghost" id="sp">Dengar</button></div>')+'<button class="main" id="go" style="margin-top:12px">'+(done?'Soal berikutnya':'Periksa Jawaban')+'</button>';
 const ty=$('ty');if(done)ty.value=q.typed||'';else{ty.oninput=e=>{if(e.isComposing)return;const n=r2k(ty.value,!!s.kata);if(n!==ty.value)ty.value=n};ty.onkeydown=e=>{if(e.key==='Enter'&&!e.isComposing){e.preventDefault();tyGo()}};try{ty.focus()}catch(_){}}
 const sb=$('sp');if(sb)sb.onclick=()=>speak(t.v||t.k);$('go').onclick=tyGo}
function tyGo(){const s=ST[S.stage],t=q.t;if(done){next();return}
 let v=r2k($('ty').value,!!s.kata).replace(/n$/,'ん');if(!nrt(v))return;
 const ok=tyAcc(t).includes(nrt(v));recd(ok,t.k);q.typed=v;
 const kanjiNote=ok&&HAS_KANJI.test(t.k)&&nrt(v)!==nrt(t.k)?' Ejaan kanjinya: '+t.k+'.':'';
 q.res='<div class="fb '+(ok?'ok':'no')+'"><b>'+(ok?'Benar.':'Belum tepat.')+'</b> '+(ok?'':'Jawabanmu: '+v+'. ')+'Jawaban: <b>'+t.k+'</b>'+(t.v&&t.v!==t.k?' ('+t.v+')':'')+' · '+t.r+(t.m?' · '+t.m:'')+kanjiNote+'</div>';
 done=true;save();render();if(S.auto!==false)speak(t.v||t.k)}
