// ===== v2: mikrofon yang tahan banting =====
function voice(box,prompt,cb,man){const SR=SRC();
 const fb=why=>{box.innerHTML='<div class="fb no">'+why+'</div><div class="mu">Cara lain yang tetap jalan: ketuk kolom di bawah, tekan ikon mikrofon di keyboard (Gboard, bahasa Jepang) lalu bicara, atau ketik jawabanmu.</div><div class="row" style="justify-content:center;gap:6px"><input id="vt" lang="ja" placeholder="日本語で…" style="flex:1;min-width:0;padding:10px;font-size:18px;border-radius:10px;border:1px solid var(--bd);background:var(--sf);color:var(--tx)"><button class="ghost" id="vg">Kirim</button></div>'+(man?'<div class="mu" style="margin-top:8px">'+MAN+'</div>':'');const i=$('vt'),g=$('vg');g.onclick=()=>{if(i.value.trim())cb([i.value.trim()])};i.onkeydown=e=>{if(e.key==='Enter')g.click()}};
 if(!SR){fb('Browser ini tidak mendukung pengenalan suara.');return}
 let got=false;const r=new SR();r.lang='ja-JP';r.maxAlternatives=3;r.continuous=false;r.interimResults=false;
 box.innerHTML='<div class="mu">'+prompt+'</div>';
 r.onresult=e=>{got=true;cb(Array.from(e.results[0]).map(a=>a.transcript))};
 r.onerror=e=>{got=true;const m={'not-allowed':'Mikrofon diblokir. Ini biasanya terjadi kalau file dibuka dari WhatsApp atau penyimpanan (alamat content:// atau file://), karena Chrome hanya mengizinkan suara di halaman https.','service-not-allowed':'Layanan suara diblokir oleh browser. File yang dibuka dari penyimpanan (content:// atau file://) tidak boleh memakai mikrofon.','no-speech':'Tidak ada suara yang terdengar. Dekatkan HP ke mulut lalu coba lagi.','audio-capture':'Mikrofon tidak terdeteksi atau sedang dipakai aplikasi lain.','network':'Pengenalan suara butuh internet.','language-not-supported':'Bahasa Jepang belum terpasang untuk pengenalan suara di HP ini.'};fb(m[e.error]||'Mikrofon tidak bisa dipakai ('+e.error+').')};
 r.onend=()=>{if(!got)fb('Tidak ada hasil suara. Coba lagi atau pakai cara lain di bawah.')};
 try{r.start()}catch(e){fb('Mikrofon tidak bisa dimulai.')}}
function listen(){const t=q.t;voice($('fb'),'Mendengarkan… ucapkan kalimatnya',L=>{let best=0,h='';L.forEach(x=>{const p=Math.max(simil(t.k,x),simil(t.v,x));if(p>=best){best=p;h=x}});const pct=Math.round(best*100);rec(pct>=60,h,pct)},1)}
function micPractice(){const box=$('pf');voice(box,'Mendengarkan…',L=>{let b=null;L.forEach(x=>{const p=pr(q.t,x);if(!b||p.pct>b.pct){b=p;b.h=x}});box.innerHTML='<div class="fb '+(b.pct>=60?'ok':'no')+'"><b>'+(b.pct>=85?'Pengucapan sangat jelas!':b.pct>=60?'Cukup jelas.':'Belum jelas, coba lagi pelan-pelan.')+'</b> Terdengar: '+b.h+' ('+b.pct+'%)'+b.html+'</div>'})}
function micAnswer(){const box=$('pf');voice(box,'Ucapkan balasanmu…',L=>{let best={p:0};L.forEach(x=>q.o.forEach(o=>{const p=align(o.j||'',x).sc;if(p>best.p)best={p,o,h:x}}));if(best.p<.4){box.innerHTML='<div class="fb no">Belum terbaca jelas. Coba lagi lebih pelan, atau pilih dengan klik.</div>';return}q.heard=best.h+' ('+Math.round(best.p*100)+'%)';sel=best.o.r;check()})}

