 const kb=(a,b)=>{const o=[],B={b:1};R.slice(a,b).forEach(r=>{const c=r.c;if(r.n==='ya')o.push(c[0],B,c[1],B,c[2]);else if(r.n==='wa')o.push(c[0],B,B,B,c[1],c[2],B,B,B,B);else o.push(...c)});return o};
