const KR={};Object.entries(RK).forEach(([r,k])=>{if(!KR[k])KR[k]=r});
const k2h=s=>s.replace(/[\u30a1-\u30f6]/g,c=>String.fromCharCode(c.charCodeAt(0)-96));
function k2r(s){s=k2h(s);let o='',i=0,db=false,la='';const P={'。':'.','、':',','？':'?','！':'!','　':' '};
 while(i<s.length){const c=s[i],n=s[i+1];
  if(c==='っ'){db=true;i++;continue}
  if(c==='ー'){o+=la;i++;continue}
  if(c==='ん'){o+=(n&&'あいうえおやゆよ'.includes(n))?"n'":'n';la='n';i++;continue}
  let r,l=1;if(n&&'ゃゅょぁぃぅぇぉ'.includes(n)&&KR[c+n]){r=KR[c+n];l=2}else r=KR[c];
  if(r===undefined){o+=P[c]!==undefined?P[c]:c;i++;db=false;continue}
  if(db){r=(r[0]==='c'?'t':r[0])+r;db=false}
  o+=r;la=r.slice(-1);i+=l}
 return o}
