function nextTopic(C){if(!C.Q.length){const f=sh(FTP.filter(t=>!C.done||!C.done.has(t.id)));C.Q=f.length?f:sh(FTP.slice())}const T=C.Q.shift();(C.done=C.done||new Set()).add(T.id);return T}
