 if(!hasJa||n.length<2)return{k:'すみません、もういちど おねがいします。にほんごで おねがいします。',x:'Maaf, tolong ulangi dalam bahasa Jepang.',s:ctx?ctx.s:[],l:0,better:ctx?ctx.s[0][0]:'',bh:ctx?ctx.s[0][1]:''};
 if(/(さようなら|さよなら|じゃあね|じゃね|またね|しつれいします|バイバイ)/.test(n))return{k:'はい、おはなし たのしかったです。またね！',x:'Ya, ngobrolnya seru. Sampai nanti!',s:[],end:1,l:2};
 if(/(もういちど|もういっかい|ゆっくり|くりかえ)/.test(n))return{k:C.last.k,x:C.last.x,s:C.last.s||[],slow:1,l:2};
 if(/(なんじ)/.test(n))return side('いま '+clockK()+'です。','Waktu sekarang sudah disebut.','Pukul '+new Date().toTimeString().slice(0,5));
 if(/(なんようび|なんがつ|なんにち|なんねん|きょうは)/.test(n)&&Q){const d=new Date();return side('きょうは '+MN[d.getMonth()+1]+' '+dayK(d.getDate())+'、'+WK[d.getDay()]+'です。','Tanggal dan hari sudah disebut.',new Date().toLocaleDateString('id-ID',{weekday:'long',day:'numeric',month:'long',year:'numeric'}))}
 if(Q||/あなたは|そちらは/.test(n)){for(const id in KWT){if(KWT[id].test(n)){const T=FTP.find(z=>z.id===id);C.ctx=T;return{k:T.a+' あなたは どうですか。',x:T.ax+' Kalau kamu?',s:T.s,l:2}}}
  if(/(あなたは|そちらは)/.test(n)&&ctx)return{k:ctx.a+' ',x:ctx.ax,s:ctx.s,l:2,keep:1,k2:1}}
