 if(/(ありがとう)/.test(n))return side('どういたしまして。','Sama-sama.');
 if(/(ごめん|すみません|すいません)/.test(n)&&n.length<12)return side('だいじょうぶですよ。','Tidak apa-apa.');
 if(/(わかりません|わからない)/.test(n))return{k:'だいじょうぶです。たとえば、「'+(ctx?ctx.s[0][0]:'はい')+'」と いえます。'+(ctx?ctx.q:''),x:'Tidak apa-apa. Contoh jawaban sudah ditunjukkan.',s:ctx?ctx.s:[],l:1,better:ctx?ctx.s[0][0]:'',bh:ctx?ctx.s[0][1]:''};
 if(/(じょうず|すごい)/.test(n))return side('ありがとうございます。まだまだです。','Terima kasih, masih harus belajar.');
 if(/(はじめまして)/.test(n)&&!C.hi){C.hi=1;return side('はじめまして。さくらです。よろしく おねがいします。','Salam kenal, saya Sakura.')}
 if(/(こんにちは|こんばんは|おはよう)/.test(n)&&n.length<14)return side('こんにちは！','Halo!');
 let pre=[REAC[Math.floor(Math.random()*REAC.length)]];
